mapper.select:
SELECT t1.workshop_id, t1.process_id, t1.team_id, t1.inspection_quantity, t1.totalWage, mbw.name AS workshop_name, mbp.name AS process_name, mbtul.user_name AS team_leader_user_name, mbp.product_type FROM ( SELECT myc.workshop_id, myc.process_id, myc.team_id, SUM(IFNULL(mbptr.inspection_quantity, 0)) AS inspection_quantity, SUM(myc.wage) AS totalWage FROM mes_yield_confirm myc LEFT JOIN mes_building_produce_team_report mbptr ON mbptr.bool_delete_enum = FALSE AND mbptr.id = myc.produce_team_report_id LEFT JOIN mes_contract_project_statistics_config_link mcpscl ON mcpscl.bool_delete_enum = FALSE AND mcpscl.contract_project_id = myc.contract_project_id WHERE myc.bool_delete_enum = FALSE
AND mcpscl.statistics_mode = #{statisticsModeEnum}
AND myc.workshop_id = #{workshopId}
AND date_format(myc.reporting_time, '%Y-%m') = date_format(#{selectedDate}, '%Y-%m')
GROUP BY myc.workshop_id, myc.process_id, myc.team_id ) t1 LEFT JOIN mes_building_workshop mbw ON mbw.id = t1.workshop_id LEFT JOIN mes_building_process mbp ON t1.process_id = mbp.id LEFT JOIN mes_building_team_user_link mbtul ON mbtul.team_id = t1.team_id AND mbtul.bool_leader_enum = 1 AND mbtul.bool_delete_enum = FALSE

SELECT all_month.month_value, ifnull(t1.totalInboundQuantity, 0) as total_inbound_quantity FROM ( SELECT 1 AS month_value UNION ALL SELECT 2 AS month_value UNION ALL SELECT 3 AS month_value UNION ALL SELECT 4 AS month_value UNION ALL SELECT 5 AS month_value UNION ALL SELECT 6 AS month_value UNION ALL SELECT 7 AS month_value UNION ALL SELECT 8 AS month_value UNION ALL SELECT 9 AS month_value UNION ALL SELECT 10 AS month_value UNION ALL SELECT 11 AS month_value UNION ALL SELECT 12 AS month_value ) all_month LEFT JOIN ( SELECT MONTH(mbwr.create_time) AS current_month, SUM(IFNULL(mbwr.quantity, 0) * IFNULL(ta.net_weight, 0) / 1000) AS totalInboundQuantity FROM mes_building_warehouse_record mbwr LEFT JOIN tech_artifact ta ON ta.id = mbwr.product_id and ta.bool_delete_enum = FALSE WHERE mbwr.bool_delete_enum = FALSE AND mbwr.type = 1 AND mbwr.product_type = 2 AND YEAR(mbwr.create_time) = #{year}
AND mbwr.workshop_id = #{workshopId}
GROUP BY current_month ) t1 ON all_month.month_value = t1.current_month

SELECT lt.current_month as month_value, moa.type AS type_name, SUM((lt.totalNetWeight / moa.inventory_quantity) * moa.price) AS cost FROM mes_other_apportionment moa LEFT JOIN ( SELECT MONTH(mbwr.create_time) AS current_month, mbwr.workshop_id, SUM(IFNULL(mbwr.quantity, 0) * IFNULL(ta.net_weight, 0) / 1000) AS totalNetWeight FROM mes_building_warehouse_record mbwr LEFT JOIN tech_artifact ta ON ta.id = mbwr.product_id WHERE mbwr.bool_delete_enum = FALSE AND mbwr.product_type = 2 AND mbwr.type = 1 AND YEAR (mbwr.create_time) = #{year}
AND mbwr.workshop_id = #{workshopId}
GROUP BY current_month, mbwr.workshop_id ) lt ON lt.workshop_id = moa.workshop_id WHERE moa.bool_delete_enum = FALSE AND moa.status = true GROUP BY lt.current_month, moa.type
